import json
import os
from typing import Any, Dict, Optional

import boto3
from botocore.config import Config


class DeadLetterPublisher:
    def __init__(self, queue_url: Optional[str] = None, region_name: Optional[str] = None) -> None:
        self.queue_url = queue_url or os.environ["AWS_SQS_DEAD_LETTER_QUEUE_URL"]
        self.region_name = region_name or os.environ.get("AWS_REGION") or os.environ.get("AWS_DEFAULT_REGION") or "us-east-1"
        self.sqs = boto3.client("sqs", region_name=self.region_name, config=Config(retries={"max_attempts": 10, "mode": "standard"}))

    def send_failed_message(
        self,
        message_body: str,
        error: str,
        original_message_id: Optional[str] = None,
        attributes: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        payload = {
            "original_message_body": message_body,
            "error": error,
            "original_message_id": original_message_id,
            "attributes": attributes or {},
        }

        response = self.sqs.send_message(
            QueueUrl=self.queue_url,
            MessageBody=json.dumps(payload),
            MessageAttributes={
                "dead_letter_reason": {
                    "StringValue": error[:256],
                    "DataType": "String",
                }
            },
        )

        return {
            "provider": "aws_sqs",
            "dead_letter_queue_url": self.queue_url,
            "message_id": response.get("MessageId"),
            "md5_of_body": response.get("MD5OfMessageBody"),
        }
